"use client";
import { useId, type ReactNode } from "react";
import {
  Badge,
  Button,
  ButtonGroup,
  Card,
  Heading,
  List,
  ListRow,
  Result,
  Skeleton,
  Stack,
  Status,
  Text,
  Trace,
  type Tone,
  type TraceEvent,
} from "@openboa/yogurt";

const states = {
  queued: { label: "Queued", tone: "neutral" },
  running: { label: "Running", tone: "neutral" },
  blocked: { label: "Blocked", tone: "warning" },
  failed: { label: "Failed", tone: "danger" },
  complete: { label: "Complete", tone: "success" },
  cancelled: { label: "Cancelled", tone: "neutral" },
} satisfies Record<string, { label: string; tone: Tone }>;

export interface RunRecord {
  id: string;
  title: string;
  time?: string;
  state: keyof typeof states;
  summary?: string;
  steps: readonly TraceEvent[];
  result?: ReactNode;
  canRetry?: boolean;
  canCancel?: boolean;
  pending?: boolean;
}

export function RunInspector({
  runs,
  selectedId,
  onSelect,
  onRetry,
  onCancel,
  renderResult,
  loading,
}: {
  runs: readonly RunRecord[];
  selectedId?: string;
  onSelect: (id: string) => void;
  onRetry?: (id: string) => void;
  onCancel?: (id: string) => void;
  renderResult?: (run: RunRecord) => ReactNode;
  loading?: boolean;
}) {
  const detailId = useId();
  const current = runs.find((run) => run.id === selectedId);
  const status = current && states[current.state];
  const canRetry =
    current?.canRetry && (current.state === "blocked" || current.state === "failed");
  const canCancel =
    current?.canCancel &&
    (current.state === "queued" || current.state === "running" || current.state === "blocked");
  return (
    <div className="yg-run-inspector">
      <div role="region" aria-label="Run history" className="yg-run-inspector-layout">
      <Card title="Run history" density="compact">
        {loading ? (
          <Skeleton label="Loading runs" />
        ) : runs.length === 0 ? (
          <Result title="No runs yet" />
        ) : (
          <List label="Runs" divided>
            {runs.map((run) => (
              <ListRow
                key={run.id}
                title={run.title}
                inlineMeta={
                  <Badge tone={states[run.state].tone}>
                    {states[run.state].label}
                  </Badge>
                }
                description={run.time}
                current={run.id === selectedId}
                onActivate={() => onSelect(run.id)}
              />
            ))}
          </List>
        )}
      </Card>
      {!loading && runs.length > 0 && (
        current && status ? (
          <Card
            key={current.id}
            title={current.title}
            description={current.summary}
            headerAction={<Status tone={status.tone}>{status.label}</Status>}
            action={
              ((canRetry && onRetry) || (canCancel && onCancel)) ? (
                <ButtonGroup label="Run actions" justify="end">
                  {canCancel && onCancel && (
                    <Button
                      emphasis="quiet"
                      size="compact"
                      pending={current.pending}
                      onClick={() => onCancel(current.id)}
                    >
                      Cancel run
                    </Button>
                  )}
                  {canRetry && onRetry && (
                    <Button
                      emphasis="filled"
                      tone="brand"
                      pending={current.pending}
                      onClick={() => onRetry(current.id)}
                    >
                      Retry run
                    </Button>
                  )}
                </ButtonGroup>
              ) : undefined
            }
          >
            <Stack role="region" aria-labelledby={detailId} gap={12}>
              <span id={detailId} className="yg-sr-only">{current.title}</span>
              {current.steps.length > 0 && <Trace label="Steps" events={[...current.steps]} />}
              {(current.result != null || renderResult) && (
                <Stack gap={4}>
                  <Heading level={4}>Result</Heading>
                  {current.result}
                  {renderResult?.(current)}
                </Stack>
              )}
            </Stack>
          </Card>
        ) : (
          <Card density="compact">
            <Result title="Select a run to see its details" />
          </Card>
        )
      )}
      </div>
    </div>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import {
  AgentAvatar, Button, Heading, Inline, ProjectMark, SearchField,
  SidebarContent, SidebarFooter, SidebarGroup, SidebarHeader, SidebarItem,
  SidebarSubmenu, Stack, Text, type AgentSummary,
} from "@openboa/yogurt";

export function AgentSidebar({
  agents, currentId, onSelect, onNew, footer,
}: {
  agents: readonly AgentSummary[];
  currentId?: string;
  onSelect: (id: string) => void;
  onNew?: () => void;
  footer?: ReactNode;
}) {
  const [query, setQuery] = useState("");
  const term = query.trim().toLowerCase();
  const available = agents.filter((agent) => (agent.name + " " + (agent.role ?? "")).toLowerCase().includes(term));
  const pinned = available.filter((agent) => agent.pinned);
  const team = available.filter((agent) => !agent.pinned);
  const rows = (members: readonly AgentSummary[]) => members.map((agent) => (
    <SidebarItem key={agent.id} label={agent.name} active={agent.id === currentId}
      icon={agent.avatar ?? (agent.art && <AgentAvatar agent={agent.art} state={agent.state} size={20} label="" />)}
      badge={agent.unread && <span className="yg-signal-dot" role="img" aria-label="Unread" />} onSelect={() => onSelect(agent.id)} />
  ));

  return (
    <>
      <SidebarHeader compact={<ProjectMark project="openboa" size={24} label="" />}>
        <Stack gap={8}>
          <Inline gap={8}><ProjectMark project="openboa" size={20} label="" /><Heading level={4}>Agents</Heading></Inline>
          <SearchField label="Find an agent" placeholder="Find an agent" hiddenLabel size="compact" value={query} onValueChange={setQuery} />
        </Stack>
      </SidebarHeader>
      <SidebarContent label="Agents">
        {pinned.length > 0 && <SidebarGroup label="Pinned">{rows(pinned)}</SidebarGroup>}
        {team.length > 0 && <SidebarSubmenu label="Team" containsCurrent={team.some((agent) => agent.id === currentId)} defaultOpen>{rows(team)}</SidebarSubmenu>}
        {!available.length && <Text variant="help">{term ? "No matching agents." : "No agents available."}</Text>}
      </SidebarContent>
      {(onNew || footer) && (
        <SidebarFooter>
          {onNew && <Button emphasis="soft" onClick={onNew}>New conversation</Button>}
          {footer}
        </SidebarFooter>
      )}
    </>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import {
  Count, Heading, IconButton, Inline, ProjectMark, SearchField, SidebarContent,
  SidebarFooter, SidebarGroup, SidebarHeader, SidebarItem, SidebarSubmenu, Stack, Text,
  type Project,
} from "@openboa/yogurt";

type Destination = { id: string; title: string; href?: string; unread?: number };

export function ProjectSidebar({
  title, mark, sections, currentId, onSelect, onAdd, footer,
}: {
  title: string;
  mark: Project;
  sections: readonly { id: string; title: string; icon?: ReactNode; items: readonly Destination[] }[];
  currentId?: string;
  onSelect?: (id: string) => void;
  onAdd?: () => void;
  footer?: ReactNode;
}) {
  const [query, setQuery] = useState("");
  const term = query.trim().toLowerCase();
  const visible = sections.map((section) => ({
    ...section,
    items: section.title.toLowerCase().includes(term) ? section.items :
      section.items.filter((item) => item.title.toLowerCase().includes(term)),
  })).filter((section) => section.items.length > 0);

  return (
    <>
      <SidebarHeader compact={<ProjectMark project={mark} label="" size={24} />}>
        <Stack gap={8}>
          <Inline gap={8}><ProjectMark project={mark} label="" size={20} /><Heading level={4}>{title}</Heading></Inline>
          <SearchField label="Find a view" placeholder="Find a view" hiddenLabel size="compact" value={query} onValueChange={setQuery} />
        </Stack>
      </SidebarHeader>
      <SidebarContent label={title + " views"}>
        <SidebarGroup label="Workspace" action={onAdd &&
          <IconButton icon="plus" size="compact" label="Add project view" onClick={onAdd} />}>
          {visible.map((section) => (
            <SidebarSubmenu key={section.id} label={section.title} icon={section.icon}
              containsCurrent={section.items.some((item) => item.id === currentId)} defaultOpen>
              {section.items.map((item) => (
                <SidebarItem key={item.id} label={item.title} href={item.href}
                  active={item.id === currentId} onSelect={onSelect && (() => onSelect(item.id))}
                  badge={item.unread ? <Count value={item.unread} label="unread" /> : undefined} />
              ))}
            </SidebarSubmenu>
          ))}
          {!visible.length && <Text variant="help">{term ? "No matching views." : "No project views yet."}</Text>}
        </SidebarGroup>
      </SidebarContent>
      {footer && <SidebarFooter>{footer}</SidebarFooter>}
    </>
  );
}
